use super::*;
use serde_json::json;
fn view(v:Value)->Value{serde_json::to_value(project(&v,Some(34),&["network".into()],42).unwrap()).unwrap()}
#[test]fn missing_fields_stay_unknown(){let v=view(json!({}));assert_eq!(v["wifi"]["enabled"],Value::Null);assert_eq!(v["wifi"]["nearby"],Value::Null);assert_eq!(v["activeVpns"],Value::Null);assert_eq!(v["hotspot"]["supported"],Value::Null);}
#[test]fn explicit_zero_false_and_empty_are_preserved(){let v=view(json!({"wifiEnabled":false,"wifiConnected":false,"wifiSignal":0,"wifiNetworks":[],"vpnActive":[]}));assert_eq!(v["wifi"]["enabled"],false);assert_eq!(v["wifi"]["signal"],0);assert_eq!(v["wifi"]["nearby"]["observedRows"],0);assert_eq!(v["wifi"]["nearby"]["complete"],true);assert_eq!(v["activeVpns"]["entries"],json!([]));}
#[test]fn independent_radios_do_not_claim_whole_network_is_off(){let v=view(json!({"wifiEnabled":false,"ethernetConnected":true,"cellularConnected":false}));assert_eq!(v["wifi"]["enabled"],false);assert_eq!(v["ethernetConnected"],true);assert_eq!(v["cellularConnected"],false);}
#[test]fn private_native_fields_and_errors_never_pass_through(){let v=view(json!({"wifiSSID":"Casa","wifiIP":"PRIVATE_IP","wifiBSSID":"PRIVATE_MAC","lastError":"PRIVATE_PASSWORD","credentials":{"psk":"PRIVATE_KEY"},"wifiNetworks":[{"ssid":"Casa","bssid":"PRIVATE_ROW_MAC","password":"PRIVATE_PSK","connected":true}],"vpnProfiles":[{"name":"VPN","uuid":"PRIVATE_UUID","secret":"PRIVATE_VPN"}]}));let s=v.to_string();assert!(!s.contains("PRIVATE"),"{s}");assert_eq!(v["wifi"]["currentName"],"Casa");assert_eq!(v["wifi"]["nearby"]["entries"][0]["connected"],true);assert_eq!(v["readOnly"],true);}
#[test]fn duplicate_names_are_not_merged_or_promoted_into_connection_identity(){let v=view(json!({"wifiSSID":"Mesmo nome","wifiNetworks":[{"ssid":"Mesmo nome","connected":false},{"ssid":"Mesmo nome","connected":true}],"vpnProfiles":[{"name":"Igual"},{"name":"Igual"}]}));assert_eq!(v["wifi"]["nearby"]["entries"].as_array().unwrap().len(),2);assert_eq!(v["wifi"]["nearby"]["entries"][0]["connected"],false);assert_eq!(v["vpnProfiles"]["entries"].as_array().unwrap().len(),2);assert!(!v.to_string().contains("target"));}
#[test]fn invalid_rows_are_explicitly_partial(){let v=view(json!({"wifiNetworks":[{"ssid":"Boa"},null,{"ssid":"bad\nname"},{"ssid":"\u{202e}spoof"}]}));assert_eq!(v["wifi"]["nearby"]["complete"],false);assert_eq!(v["wifi"]["nearby"]["observedRows"],4);assert_eq!(v["wifi"]["nearby"]["rejectedRows"],3);assert_eq!(v["warnings"],json!(["invalidRows"]));}
#[test]fn unsupported_old_saved_catalogue_cannot_be_inferred_from_nearby_saved_flags(){let s=project(&json!({"wifiNetworks":[{"ssid":"Saved","saved":true}],"savedWifiNetworks":[]}),Some(25),&["network".into()],42).unwrap();assert!(s.wifi.saved.is_none());assert_eq!(s.warnings,vec!["savedNetworksUnsupported"]);assert!(s.hotspot.supported.is_none());}
#[test]fn missing_api_version_does_not_certify_new_capabilities(){let s=project(&json!({"hotspotSupported":true,"savedWifiNetworks":[]}),None,&["network".into()],42).unwrap();assert!(s.wifi.saved.is_none());assert!(s.hotspot.supported.is_none());}
#[test]fn null_collections_are_unknown_not_empty(){let v=view(json!({"wifiDevices":null,"wifiNetworks":null,"vpnProfiles":null}));assert!(v["wifi"]["devices"].is_null());assert!(v["wifi"]["nearby"].is_null());assert!(v["vpnProfiles"].is_null());}
#[test]fn wrong_collection_type_and_oversized_collections_are_not_truncated_as_complete(){let v=view(json!({"wifiNetworks":"PRIVATE_TYPE","wifiDevices":vec![json!({"name":"wlan"});33]}));assert!(v["wifi"]["nearby"].is_null());assert!(v["wifi"]["devices"].is_null());assert_eq!(v["warnings"],json!(["invalidCollection","collectionTooLarge"]));}
#[test]fn wrong_scalar_types_and_out_of_range_signals_stay_unknown(){let v=view(json!({"wifiEnabled":"true","wifiConnected":0,"wifiSignal":101,"wifiNetworks":[{"ssid":"Casa","signal":-1,"secured":"yes"}]}));assert!(v["wifi"]["enabled"].is_null());assert!(v["wifi"]["connected"].is_null());assert!(v["wifi"]["signal"].is_null());assert!(v["wifi"]["nearby"]["entries"][0]["signal"].is_null());assert!(v["wifi"]["nearby"]["entries"][0]["secured"].is_null());}
#[test]fn connection_states_are_explicit_not_raw_errors(){let v=view(json!({"vpnActive":[{"name":"VPN","state":"activated"},{"name":"VPN2","state":"PRIVATE_ERROR"}]}));assert_eq!(v["activeVpns"]["entries"][0]["state"],"activated");assert!(v["activeVpns"]["entries"][1]["state"].is_null());assert!(!v.to_string().contains("PRIVATE_ERROR"));}
#[test]fn invalid_snapshot_capability_shape_and_timestamp_are_rejected(){assert_eq!(project(&json!({}),Some(34),&[],42).err(),Some(Error::MissingCapability));assert_eq!(project(&json!([]),Some(34),&["network".into()],42).err(),Some(Error::InvalidState));assert_eq!(project(&json!({}),Some(34),&["network".into()],0).err(),Some(Error::InvalidTimestamp));}
#[test]fn oversized_and_control_character_labels_cannot_leak_partial_names(){let v=view(json!({"wifiSSID":"x".repeat(129),"vpnProfiles":[{"name":"bad\tname"}],"wifiDevices":[{"name":"good"},{"name":"x".repeat(65)}]}));assert!(v["wifi"]["currentName"].is_null());assert_eq!(v["vpnProfiles"]["rejectedRows"],1);assert_eq!(v["wifi"]["devices"]["rejectedRows"],1);}

#[test]fn epoch_millisecond_values_that_cannot_reach_javascript_date_are_rejected(){for at in [8_640_000_000_000_001,u64::MAX]{assert_eq!(project(&json!({}),Some(34),&["network".into()],at).err(),Some(Error::InvalidTimestamp));}}
#[test]fn exact_javascript_date_boundary_and_current_epoch_milliseconds_are_preserved(){for at in [1_792_500_000_000,8_640_000_000_000_000]{let s=project(&json!({}),Some(34),&["network".into()],at).unwrap();assert_eq!(serde_json::to_value(s).unwrap()["observedAt"].as_u64(),Some(at));}}
